using System.Windows.Forms;

static class Program
{
    [STAThread]
    static void Main()
    {
        ApplicationConfiguration.Initialize();

        var form = new Form();

        // .NET 9 behavioral change: StatusStrip default renderer changed.
        // Explicitly set RenderMode to restore previous appearance.
        var statusStrip = new StatusStrip();
        statusStrip.RenderMode = ToolStripRenderMode.System;
        form.Controls.Add(statusStrip);

        Application.Run(form);
    }
}

using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

class MyEditor : UITypeEditor
{
    public override object? EditValue(
        System.ComponentModel.ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService == null)
            return value;

        // .NET 9 breaking change: DropDownControl parameter is now non-nullable.
        // Guard against passing null to avoid ArgumentNullException.
        var control = CreateDropDownControl(value);
        if (control is not null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
        }

        return value;
    }

    private Control? CreateDropDownControl(object? currentValue)
    {
        // Returns null when no valid dropdown can be created
        if (currentValue is not string s)
            return null;

        var listBox = new ListBox();
        listBox.Items.Add(s);
        return listBox;
    }

    private object? GetValueFromControl(Control control)
    {
        if (control is ListBox lb && lb.SelectedItem != null)
            return lb.SelectedItem;
        return null;
    }
}

